Proceso ContarReprobados
    Definir cantidad Como Entero;
    Definir i Como Entero;
    Definir nota Como Entero;
    Definir reprobados Como Entero;
    Leer cantidad;
    reprobados <- 0;
    Para i <- 1 Hasta cantidad Hacer
        Leer nota;
        Si nota < 5 Entonces
            reprobados <- reprobados + 1;
        FinSi
    FinPara
    Escribir reprobados;
FinProceso

